public class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {
    // Running totals for the whole job. Database.Stateful is required so that
    // these values survive between chunk transactions and are visible in finish().
    private Integer recordsUpdated = 0;
    private Integer recordsFailed = 0;
    private Decimal overdueAmount = 0;

    public OverdueInvoiceBatch() {
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
            AND Due_Date__c < :Date.today()
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        List<FB_Invoice__c> invoices = new List<FB_Invoice__c>();
        for (SObject sobj : scope) {
            if (sobj instanceof FB_Invoice__c) {
                FB_Invoice__c inv = (FB_Invoice__c) sobj;
                inv.Status__c = 'Overdue';
                invoices.add(inv);
            }
        }

        if (invoices.isEmpty()) {
            return;
        }

        // allOrNone = false so a single bad record (e.g. blocked by the
        // validation rule) does not roll back the rest of the chunk.
        List<Database.SaveResult> results = Database.update(invoices, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                recordsUpdated++;
                Decimal amount = invoices[i].Amount__c;
                if (amount != null) {
                    overdueAmount += amount;
                }
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c();
        summary.Job_Name__c = 'OverdueInvoiceBatch';
        summary.Records_Updated__c = recordsUpdated;
        summary.Records_Failed__c = recordsFailed;
        summary.Overdue_Amount__c = overdueAmount;
        insert summary;
    }
}
