public with sharing class ExchangeRateClient {
    private static final String NAMED_CREDENTIAL_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (baseCurrency == null) {
            throw new ExchangeRateException('Base currency is required.');
        }
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        String base = baseCurrency.trim().toUpperCase();
        if (!isValidCurrencyCode(base)) {
            throw new ExchangeRateException('Invalid base currency: ' + baseCurrency);
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            if (quote == null) {
                throw new ExchangeRateException('Quote currency cannot be null.');
            }
            String normalized = quote.trim().toUpperCase();
            if (!isValidCurrencyCode(normalized)) {
                throw new ExchangeRateException('Invalid quote currency: ' + quote);
            }
            normalizedQuotes.add(normalized);
        }

        List<String> quoteList = new List<String>(normalizedQuotes);
        quoteList.sort();
        String symbols = String.join(quoteList, ',');

        HttpResponse response = sendRequest(base, symbols);
        if (response.getStatusCode() == 503) {
            response = sendRequest(base, symbols);
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with status ' + response.getStatusCode() + '.'
            );
        }

        Map<String, Object> rates = parseRates(response.getBody());

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalizedQuotes) {
            Object rawRate = rates.get(code);
            if (rawRate == null) {
                throw new ExchangeRateException('Missing exchange rate for ' + code + '.');
            }
            Decimal rate = toDecimal(rawRate);
            if (rate == null) {
                throw new ExchangeRateException('Invalid exchange rate for ' + code + '.');
            }
            result.put(code, rate);
        }
        return result;
    }

    private static Boolean isValidCurrencyCode(String code) {
        if (code == null || code.length() != 3) {
            return false;
        }
        return CURRENCY_CODE_PATTERN.matcher(code).matches();
    }

    private static HttpResponse sendRequest(String base, String symbols) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(NAMED_CREDENTIAL_ENDPOINT + '?base=' + base + '&symbols=' + symbols);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        try {
            return new Http().send(request);
        } catch (System.CalloutException e) {
            throw new ExchangeRateException('Callout failed: ' + e.getMessage());
        }
    }

    private static Map<String, Object> parseRates(String body) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Empty exchange rate response body.');
        }
        try {
            Map<String, Object> root = (Map<String, Object>) JSON.deserializeUntyped(body);
            Object ratesObj = root.get('rates');
            if (ratesObj == null) {
                throw new ExchangeRateException('Missing rates in exchange rate response.');
            }
            return (Map<String, Object>) ratesObj;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }
    }

    private static Decimal toDecimal(Object value) {
        try {
            if (value instanceof Decimal) {
                return (Decimal) value;
            }
            if (value instanceof Double) {
                return Decimal.valueOf((Double) value);
            }
            if (value instanceof Integer || value instanceof Long) {
                return Decimal.valueOf(String.valueOf(value));
            }
            if (value instanceof String) {
                return Decimal.valueOf((String) value);
            }
            return null;
        } catch (Exception e) {
            return null;
        }
    }
}
