/**
 * Parses free-text supplier payment terms such as "NET 30", "net30",
 * "Net  45" or "DUE ON RECEIPT" and turns them into net days / due dates.
 */
public class PaymentTerms {

    /** Maximum number of net days accepted. */
    private static final Integer MAX_NET_DAYS = 180;

    /** "NET" (any case) + optional whitespace + 1..3 digits, nothing else. */
    private static final Pattern NET_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');

    /**
     * @param terms raw free-text payment terms (may be null)
     * @return the number of net days (0 for "DUE ON RECEIPT")
     * @throws UnsupportedTermsException  if the terms cannot be recognised
     * @throws TermsOutOfRangeException   if the net days exceed 180
     */
    public static Integer parseNetDays(String terms) {
        String trimmed = (terms == null) ? null : terms.trim();

        // Null / blank / whitespace-only input is unsupported.
        if (String.isBlank(trimmed)) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
        }

        if (trimmed.equalsIgnoreCase('DUE ON RECEIPT')) {
            return 0;
        }

        Matcher matcher = NET_PATTERN.matcher(trimmed);
        if (matcher.matches()) {
            Integer days = Integer.valueOf(matcher.group(1));
            if (days > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        // Anything else is unsupported; report the original input verbatim.
        throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }

    /**
     * @param invoiceDate the invoice date to add the net days to
     * @param terms       raw free-text payment terms
     * @return invoiceDate plus the parsed net days
     * @throws UnsupportedTermsException  if the terms cannot be recognised
     * @throws TermsOutOfRangeException   if the net days exceed 180
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
