@IsTest
private class AddressVerificationServiceTest {

    private static final String ENDPOINT = 'callout:FB_Address_API/v2/verify';

    /**
     * Mock that captures the outgoing request so the test can assert the full request contract.
     */
    private class CapturingMock implements HttpCalloutMock {
        public HttpRequest request;
        public Integer statusCode;
        public String responseBody;
        public Integer callCount = 0;

        public CapturingMock(Integer statusCode, String responseBody) {
            this.statusCode = statusCode;
            this.responseBody = responseBody;
        }

        public HttpResponse respond(HttpRequest req) {
            this.request = req;
            this.callCount++;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            res.setBody(this.responseBody);
            return res;
        }
    }

    /**
     * Mock used for the SKIPPED path: it records that a callout happened (which must not happen)
     * and returns a harmless 200 response so the service can finish normally and be asserted on.
     */
    private class ForbiddenCalloutMock implements HttpCalloutMock {
        public Integer callCount = 0;

        public HttpResponse respond(HttpRequest req) {
            this.callCount++;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(200);
            res.setBody('{"status":"VERIFIED","address":{"street":"x","city":"x","postalCode":"x","country":"x"}}');
            return res;
        }
    }

    private static Account buildAccount(String street, String city, String postalCode, String country) {
        return new Account(
            BillingStreet = street,
            BillingCity = city,
            BillingPostalCode = postalCode,
            BillingCountry = country
        );
    }

    private static String buildResponseBody(String status, String street, String city, String postalCode, String country) {
        Map<String, Object> address = new Map<String, Object>{
            'street' => street,
            'city' => city,
            'postalCode' => postalCode,
            'country' => country
        };
        Map<String, Object> body = new Map<String, Object>{
            'status' => status,
            'address' => address
        };
        return JSON.serialize(body);
    }

    @IsTest
    static void blankStreetIsSkipped() {
        Account acct = buildAccount('   ', 'City', '12345', 'Country');
        ForbiddenCalloutMock mock = new ForbiddenCalloutMock();
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status, 'Blank BillingStreet should be skipped.');
        System.assertEquals(false, result.changed, 'Skipped result must not be changed.');
        System.assertEquals(0, mock.callCount, 'No callout should be made for a blank BillingStreet.');
        System.assertEquals('   ', acct.BillingStreet, 'Account must be untouched when skipped.');
        System.assertEquals('City', acct.BillingCity, 'Account must be untouched when skipped.');
        System.assertEquals('12345', acct.BillingPostalCode, 'Account must be untouched when skipped.');
        System.assertEquals('Country', acct.BillingCountry, 'Account must be untouched when skipped.');
    }

    @IsTest
    static void nullStreetIsSkipped() {
        Account acct = buildAccount(null, 'City', '12345', 'Country');
        ForbiddenCalloutMock mock = new ForbiddenCalloutMock();
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertEquals('SKIPPED', result.status, 'Null BillingStreet should be skipped.');
        System.assertEquals(false, result.changed, 'Skipped result must not be changed.');
        System.assertEquals(0, mock.callCount, 'No callout should be made for a null BillingStreet.');
    }

    @IsTest
    static void sendsCorrectRequestContract() {
        Account acct = buildAccount('123 Main St', 'Springfield', '62701', 'USA');
        CapturingMock mock = new CapturingMock(200, buildResponseBody('VERIFIED', '123 Main St', 'Springfield', '62701', 'USA'));
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertNotEquals(null, mock.request, 'A callout should have been made.');
        System.assertEquals(1, mock.callCount, 'Exactly one callout should be made.');
        System.assertEquals('POST', mock.request.getMethod(), 'Request method must be POST.');
        System.assertEquals(ENDPOINT, mock.request.getEndpoint(), 'Request endpoint must match the API contract.');
        System.assertEquals('application/json', mock.request.getHeader('Content-Type'), 'Content-Type header must be application/json.');

        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(mock.request.getBody());
        System.assertEquals(4, body.size(), 'Request body must contain exactly the four documented fields.');
        System.assert(body.containsKey('street'), 'Request body must contain street.');
        System.assert(body.containsKey('city'), 'Request body must contain city.');
        System.assert(body.containsKey('postalCode'), 'Request body must contain postalCode.');
        System.assert(body.containsKey('country'), 'Request body must contain country.');
        System.assertEquals('123 Main St', (String) body.get('street'), 'street must come from BillingStreet.');
        System.assertEquals('Springfield', (String) body.get('city'), 'city must come from BillingCity.');
        System.assertEquals('62701', (String) body.get('postalCode'), 'postalCode must come from BillingPostalCode.');
        System.assertEquals('USA', (String) body.get('country'), 'country must come from BillingCountry.');

        System.assertEquals('VERIFIED', result.status, 'Result status must come from the response.');
        System.assertEquals(false, result.changed, 'VERIFIED must not set changed.');
    }

    @IsTest
    static void requestBodyUsesAccountFieldsExactly() {
        Account acct = buildAccount('456 Oak Ave', 'Shelbyville', '99999', 'Canada');
        CapturingMock mock = new CapturingMock(200, buildResponseBody('INVALID', '456 Oak Ave', 'Shelbyville', '99999', 'Canada'));
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertNotEquals(null, mock.request, 'A callout should have been made.');
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(mock.request.getBody());
        System.assertEquals('456 Oak Ave', (String) body.get('street'), 'street must be BillingStreet.');
        System.assertEquals('Shelbyville', (String) body.get('city'), 'city must be BillingCity.');
        System.assertEquals('99999', (String) body.get('postalCode'), 'postalCode must be BillingPostalCode.');
        System.assertEquals('Canada', (String) body.get('country'), 'country must be BillingCountry.');
    }

    @IsTest
    static void sendsCalloutWhenOnlyStreetIsProvided() {
        Account acct = buildAccount('123 Main St', null, null, null);
        CapturingMock mock = new CapturingMock(200, buildResponseBody('VERIFIED', '123 Main St', null, null, null));
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

        System.assertNotEquals(null, mock.request, 'A callout should be made when only BillingStreet is provided.');
        System.assertEquals(1, mock.callCount, 'Exactly one callout should be made.');
        System.assertEquals('VERIFIED', result.status, 'Only a blank BillingStreet should cause a skip.');
        Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(mock.request.getBody());
        System.assertEquals('123 Main St', (String) body.get('street'), 'street must come from BillingStreet.');
    }

    @IsTest
    static void verifiedResponseDoesNotChangeAccount() {
        Account acct = buildAccount('1 Old St', 'OldCity', '00000', 'OldCountry');
        CapturingMock mock = new CapturingMock(200, buildResponseBody('VERIFIED', '9 New St', 'NewCity', '99999', 'NewCountry'));
        Test.setMock(HttpCalloutMock.class, mock);

        Test.startTest();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);
        Test.stopTest();

