    // Helpers
    // ------------------------------------------------------------------

    /**
     * Asserts that the quote for the given arguments equals the expected amount and that the
     * amount is scaled to exactly two decimal places (the documented rounding).
     */
    private static void assertQuote(String label, Decimal expected, Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
