/**
 * Maintains the open-pipeline roll-up fields on Account, which cannot be maintained with
 * roll-up summary fields:
 *   FB_Open_Pipeline__c      -> SUM(Amount) of the account's open opportunities (blank Amount = 0)
 *   FB_Open_Opportunities__c -> COUNT of the account's open opportunities
 *
 * Called from OpportunityTrigger (after insert, update, delete, undelete).
 *
 * Every invocation recalculates the affected accounts from the database (the trigger records
 * are only used to find which accounts are affected), so the totals stay correct no matter
 * how many DML statements touch the same records in one transaction, and the whole thing is
 * bulk safe: one aggregate query, one Account query and at most one Account DML per execution.
 *
 * Declared without sharing so the system maintained totals cannot be left stale because the
 * running user cannot see or edit the parent Account.
 */
public without sharing class OpportunityPipelineHandler {

    public static void handle() {
        Set<Id> accountIds = affectedAccountIds();
        if (!accountIds.isEmpty()) {
            recalculate(accountIds);
        }
    }

    /**
     * Accounts whose open opportunity totals can have changed because of the current DML.
     */
    private static Set<Id> affectedAccountIds() {
        Set<Id> accountIds = new Set<Id>();

        if (Trigger.isInsert || Trigger.isUndelete) {
            for (SObject opp : Trigger.new) {
                addOpenOpportunityAccount(accountIds, opp);
            }
        } else if (Trigger.isUpdate) {
            for (SObject opp : Trigger.new) {
                SObject oldOpp = Trigger.oldMap.get((Id) opp.get('Id'));

                Id newAccountId = (Id) opp.get('AccountId');
                Id oldAccountId = (Id) oldOpp.get('AccountId');

                if (newAccountId != oldAccountId) {
                    // The opportunity moved to another account: both accounts change.
                    if (newAccountId != null) {
                        accountIds.add(newAccountId);
                    }
                    if (oldAccountId != null) {
                        accountIds.add(oldAccountId);
                    }
                    continue;
                }

                if (newAccountId == null) {
                    continue;
                }

                Boolean isOpen = !(Boolean) opp.get('IsClosed');
                Boolean wasOpen = !(Boolean) oldOpp.get('IsClosed');

                if (isOpen != wasOpen || (isOpen && (Decimal) opp.get('Amount') != (Decimal) oldOpp.get('Amount'))) {
                    accountIds.add(newAccountId);
                }
            }
        } else if (Trigger.isDelete) {
            for (SObject opp : Trigger.old) {
                addOpenOpportunityAccount(accountIds, opp);
            }
        }

        return accountIds;
    }

    private static void addOpenOpportunityAccount(Set<Id> accountIds, SObject opp) {
        if (!(Boolean) opp.get('IsClosed')) {
            Id accountId = (Id) opp.get('AccountId');
            if (accountId != null) {
                accountIds.add(accountId);
            }
        }
    }

    /**
     * Recomputes both totals for the given accounts and writes them back in a single DML.
     * Accounts without open opportunities are set to 0 / 0, never left blank.
     */
    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            pipelineByAccount.put(accountId, 0);
            openCountByAccount.put(accountId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');
            Integer openCount = (Integer) ar.get('openCount');
            pipelineByAccount.put(accountId, totalAmount == null ? 0 : totalAmount);
            openCountByAccount.put(accountId, openCount == null ? 0 : openCount);
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal pipeline = pipelineByAccount.get(account.Id);
            Integer openCount = openCountByAccount.get(account.Id);
            if (pipeline == null) {
                pipeline = 0;
            }
            if (openCount == null) {
                openCount = 0;
            }

            if (account.FB_Open_Pipeline__c != pipeline || account.FB_Open_Opportunities__c != openCount) {
                account.FB_Open_Pipeline__c = pipeline;
                account.FB_Open_Opportunities__c = openCount;
                accountsToUpdate.add(account);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
