/**
 * Unit tests for the Contacts domain class.
 *
 * Pure unit tests: no DML and no SOQL is performed. The domain class is driven
 * through the fflib mock trigger database (fflib_SObjectDomain.Test.Database)
 * and fflib_SObjectDomain.triggerHandler(Contacts.class), using fake ids from
 * fflib_IDGenerator.
 *
 * Note: the "today" date is held in a constant named TODAY_DATE on purpose -
 * Apex identifiers are case-insensitive, so a constant named TODAY would be
 * shadowed by any local variable called "today".
 */
@IsTest(isParallel=true)
private class ContactsTest {

    private static final Date TODAY_DATE = Date.today();

    // -----------------------------------------------------------------------
    // onApplyDefaults - before insert
    // -----------------------------------------------------------------------

    @IsTest
    static void insertDefaultsBlankLeadSourceToWeb() {
        Contact nullLeadSource = new Contact(LastName = 'Null Lead Source');
        Contact blankLeadSource = new Contact(LastName = 'Blank Lead Source', LeadSource = '   ');
        Contact setLeadSource = new Contact(LastName = 'Set Lead Source', LeadSource = 'Phone Inquiry');

        List<Contact> contacts = new List<Contact>{ nullLeadSource, blankLeadSource, setLeadSource };

        fflib_SObjectDomain.Test.Database.onInsert(contacts);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        Assert.areEqual('Web', nullLeadSource.LeadSource,
            'A null LeadSource should default to Web on insert');
        Assert.areEqual('Web', blankLeadSource.LeadSource,
            'A blank LeadSource should default to Web on insert');
        Assert.areEqual('Phone Inquiry', setLeadSource.LeadSource,
            'A LeadSource that is already populated should be kept on insert');
    }

    // -----------------------------------------------------------------------
    // onBeforeUpdate - HasOptedOutOfEmail
    // -----------------------------------------------------------------------

    @IsTest
    static void updateWithChangedEmailClearsOptOut() {
        Id contactId = fflib_IDGenerator.generate(Contact.SObjectType);

        Contact existing = new Contact(
            Id = contactId,
            LastName = 'Doe',
            Email = 'old@example.com',
            HasOptedOutOfEmail = true);

        Contact updated = new Contact(
            Id = contactId,
            LastName = 'Doe',
            Email = 'new@example.com',
            HasOptedOutOfEmail = true);

        fflib_SObjectDomain.Test.Database.onUpdate(
            new List<Contact>{ updated },
            new Map<Id, Contact>{ contactId => existing });

        fflib_SObjectDomain.triggerHandler(Contacts.class);

        Assert.areEqual(false, updated.HasOptedOutOfEmail,
            'A contact whose Email changed should have HasOptedOutOfEmail reset to false');
    }

    @IsTest
    static void updateWithUnchangedEmailKeepsOptOut() {
        Id contactId = fflib_IDGenerator.generate(Contact.SObjectType);

        Contact existing = new Contact(
            Id = contactId,
            LastName = 'Doe',
            Email = 'same@example.com',
            HasOptedOutOfEmail = true);

        Contact updated = new Contact(
            Id = contactId,
            LastName = 'Doe Renamed',
            Email = 'same@example.com',
            HasOptedOutOfEmail = true);

        fflib_SObjectDomain.Test.Database.onUpdate(
            new List<Contact>{ updated },
            new Map<Id, Contact>{ contactId => existing });

        fflib_SObjectDomain.triggerHandler(Contacts.class);

        Assert.areEqual(true, updated.HasOptedOutOfEmail,
            'A contact whose Email did not change should keep its HasOptedOutOfEmail value');
    }

    // -----------------------------------------------------------------------
    // onValidate - before insert
    // -----------------------------------------------------------------------

    @IsTest
    static void insertRejectsFutureBirthdate() {
        Contact futureContact = new Contact(
            LastName = 'Future Birthdate',
            Birthdate = TODAY_DATE.addDays(1));

        fflib_SObjectDomain.Test.Database.onInsert(new List<Contact>{ futureContact });
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        assertBirthdateError(futureContact);
    }

    @IsTest
    static void insertAcceptsTodayAndPastBirthdates() {
        Contact bornToday = new Contact(LastName = 'Born Today', Birthdate = TODAY_DATE);
        Contact bornInPast = new Contact(LastName = 'Born In The Past', Birthdate = TODAY_DATE.addDays(-1));
        Contact noBirthdate = new Contact(LastName = 'No Birthdate');

        fflib_SObjectDomain.Test.Database.onInsert(
            new List<Contact>{ bornToday, bornInPast, noBirthdate });
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        assertNoBirthdateError(bornToday);
        assertNoBirthdateError(bornInPast);
        assertNoBirthdateError(noBirthdate);
    }

    // -----------------------------------------------------------------------
    // onValidate - before update
    // -----------------------------------------------------------------------

    @IsTest
    static void updateRejectsFutureBirthdate() {
        Id contactId = fflib_IDGenerator.generate(Contact.SObjectType);

        Contact existing = new Contact(
            Id = contactId,
            LastName = 'Doe',
            Birthdate = TODAY_DATE.addDays(-30));

        Contact updated = new Contact(
            Id = contactId,
            LastName = 'Doe',
            Birthdate = TODAY_DATE.addDays(1));

        fflib_SObjectDomain.Test.Database.onUpdate(
            new List<Contact>{ updated },
            new Map<Id, Contact>{ contactId => existing });

        fflib_SObjectDomain.triggerHandler(Contacts.class);

        assertBirthdateError(updated);
    }

    @IsTest
    static void updateAcceptsTodayAndPastBirthdates() {
        Id todayId = fflib_IDGenerator.generate(Contact.SObjectType);
        Id pastId = fflib_IDGenerator.generate(Contact.SObjectType);

        Contact existingToday = new Contact(
            Id = todayId,
            LastName = 'Doe',
            Birthdate = TODAY_DATE.addDays(-10));

        Contact updatedToday = new Contact(
            Id = todayId,
            LastName = 'Doe',
            Birthdate = TODAY_DATE);

        Contact existingPast = new Contact(
            Id = pastId,
            LastName = 'Roe',
            Birthdate = TODAY_DATE.addDays(-10));

        Contact updatedPast = new Contact(
            Id = pastId,
            LastName = 'Roe',
            Birthdate = TODAY_DATE.addDays(-20));

        fflib_SObjectDomain.Test.Database.onUpdate(
            new List<Contact>{ updatedToday, updatedPast },
            new Map<Id, Contact>{ todayId => existingToday, pastId => existingPast });

        fflib_SObjectDomain.triggerHandler(Contacts.class);

        assertNoBirthdateError(updatedToday);
        assertNoBirthdateError(updatedPast);
    }

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    private static void assertBirthdateError(Contact theContact) {
        List<Database.Error> errors = theContact.getErrors();
        Assert.areEqual(1, errors.size(),
            'Expected exactly one validation error on the contact with a future birthdate');

        Database.Error birthdateError = errors[0];
        Assert.areEqual(Contacts.FUTURE_BIRTHDATE, birthdateError.getMessage(),
            'Unexpected validation message for a birthdate in the future');
        Assert.isTrue(isOnBirthdateField(birthdateError),
            'The future birthdate error should be attached to the Birthdate field');
    }

    private static void assertNoBirthdateError(Contact theContact) {
        Assert.areEqual(0, theContact.getErrors().size(),
            'Expected no validation errors on contact: ' + theContact.LastName);
    }

    private static Boolean isOnBirthdateField(Database.Error theError) {
        for (String fieldName : theError.getFields()) {
            if (fieldName != null && 'Birthdate'.equalsIgnoreCase(fieldName)) {
                return true;
            }
        }
        return false;
    }
}
