            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    /**
     * Called by the framework on before insert and before update.
     * For before insert the existing records map is empty.
     */
    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            // Rule 1: Amount must not be negative (insert and update)
            if (opp.Amount != null && opp.Amount < 0)
            {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            // Rule 2: a previously won opportunity's Amount is locked
            Opportunity existing = (Opportunity) existingRecords.get(opp.Id);
            if (existing != null
                && existing.StageName == 'Closed Won'
                && opp.Amount != existing.Amount)
            {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
