public with sharing class OpportunityWinService {
    private static final String CLOSED_WON = 'Closed Won';

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);
        if (opportunities == null || opportunities.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        List<Opportunity> opportunitiesToUpdate = new List<Opportunity>();
        List<Deal_Won__e> eventsToPublish = new List<Deal_Won__e>();

        for (Opportunity opp : opportunities) {
            if (opp.StageName == CLOSED_WON) {
                continue;
            }

            opp.StageName = CLOSED_WON;
            opp.CloseDate = Date.today();
            opportunitiesToUpdate.add(opp);

            Deal_Won__e dealWon = new Deal_Won__e();
            dealWon.Opportunity_Id__c = String.valueOf(opp.Id);
            dealWon.Amount__c = opp.Amount;
            eventsToPublish.add(dealWon);
        }

        if (opportunitiesToUpdate.isEmpty()) {
            return 0;
        }

        uow.registerDirty(opportunitiesToUpdate);
        for (Deal_Won__e dealWon : eventsToPublish) {
            uow.registerPublishAfterSuccessTransaction(dealWon);
        }
        uow.commitWork();

        return opportunitiesToUpdate.size();
    }
}
