/**
 * Stages one-off web gifts as NPSP Data Import (BDI) records and processes them
 * synchronously, in the caller's transaction, through NPSP's own Data Import Apex API.
 * That way NPSP's contact matching, household creation and donation processing rules
 * apply, and every staged Data Import record stays in the org as the audit trail of
 * what was imported.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1 = 'Contact1';

    /**
     * @description Stages one NPSP Data Import record per gift and processes them
     *              synchronously with NPSP's Data Import Apex API and the org's Data
     *              Import settings. Returns one ImportResult per gift, in input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1) Stage one NPSP Data Import record per gift. Nothing is written to
        //    Contacts/Opportunities here; NPSP does all of that when it processes
        //    the Data Import records.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            if (gift != null) {
                di.npsp__Contact1_Firstname__c = gift.firstName;
                di.npsp__Contact1_Lastname__c = gift.lastName;
                di.npsp__Contact1_Personal_Email__c = gift.email;
                di.npsp__Donation_Amount__c = gift.amount;
                di.npsp__Donation_Date__c = gift.giftDate;
            }
            // Donation donor is the Contact staged on Contact1; NPSP will attach the
            // donation to that contact's household account.
            di.npsp__Donation_Donor__c = DONOR_CONTACT1;
            staged.add(di);
        }

        // 2) Insert the staged rows. allOrNone = false so a single bad row cannot
        //    stop the rest of the gifts from being processed.
        List<Database.SaveResult> insertResults = Database.insert(staged, false);

        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        Map<Integer, String> insertErrors = new Map<Integer, String>();

        for (Integer i = 0; i < staged.size(); i++) {
            if (insertResults[i].isSuccess()) {
                staged[i].Id = insertResults[i].getId();
                toProcess.add(staged[i]);
            } else {
                insertErrors.put(i, insertResults[i].getErrors()[0].getMessage());
            }
        }

        // 3) Process the staged rows synchronously in this same transaction using
        //    NPSP's Data Import Apex API. Passing null for the settings name means
        //    the org's own Data Import settings (the npsp__Data_Import_Settings__c
        //    hierarchy custom setting) are used, so the org's matching rules apply.
        String processingError;
        if (!toProcess.isEmpty()) {
            try {
                npsp.BDI_DataImportService.processDataImports(toProcess, false, false, null);
            } catch (Exception e) {
                processingError = e.getMessage();
            }
        }

        // 4) Read back NPSP's results for the rows we staged.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>();
        if (!toProcess.isEmpty()) {
            processedById = new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :toProcess
            ]);
        }

        // 5) One result per gift, in input order.
        for (Integer i = 0; i < staged.size(); i++) {
            ImportResult res = new ImportResult();

            if (insertErrors.containsKey(i)) {
                res.success = false;
                res.errorMessage = insertErrors.get(i);
                results.add(res);
                continue;
            }

            npsp__DataImport__c di = processedById.get(staged[i].Id);

            if (di == null) {
                res.success = false;
                res.errorMessage = String.isNotBlank(processingError)
                    ? processingError
                    : 'The Data Import record could not be processed.';
            } else {
                res.success = (di.npsp__Status__c == STATUS_IMPORTED);
                res.contactId = di.npsp__Contact1Imported__c;
                res.opportunityId = di.npsp__DonationImported__c;

                if (res.success) {
                    res.errorMessage = null;
                } else if (String.isNotBlank(di.npsp__FailureInformation__c)) {
                    res.errorMessage = di.npsp__FailureInformation__c;
                } else if (String.isNotBlank(processingError)) {
                    res.errorMessage = processingError;
                } else {
                    res.errorMessage = 'NPSP did not import this gift (Data Import status: '
                        + di.npsp__Status__c + ').';
                }
            }

            results.add(res);
        }

        return results;
    }
}
