/**
 * Records monthly giving sign-ups coming from an external donation form as
 * Enhanced Recurring Donations (NPSP). NPSP's own scheduler creates the
 * installment Opportunities, so this service only inserts the Recurring
 * Donation records themselves.
 */
public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String RD_OBJECT = 'npe03__Recurring_Donation__c';

    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final Integer INSTALLMENT_FREQUENCY_MONTHLY = 1;

    private static final String STATUS_ACTIVE = 'Active';

    private static final Integer DAY_OF_MONTH_LAST_DAY_INPUT = 31;
    private static final String DAY_OF_MONTH_LAST_DAY = 'Last_Day';

    /**
     * npsp__Always_Use_Last_Day_Of_Month__c is exposed as a writable checkbox in some
     * NPSP releases and as a formula in others. Only write to it when the org actually
     * allows it; when it is a formula it is derived from Day of Month automatically.
     */
    private static final Boolean CAN_SET_ALWAYS_USE_LAST_DAY =
        !npe03__Recurring_Donation__c.npsp__Always_Use_Last_Day_Of_Month__c.getDescribe().isCalculated();

    /**
     * @description Creates one Enhanced Recurring Donation per request and returns the
     *              new Ids in the same order as the requests.
     * @param requests Monthly giving sign-ups coming from the donation form.
     * @return The Ids of the created Recurring Donations, in request order.
     * @throws RecurringGiftException when any request is invalid. No DML is performed
     *         in that case.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        validate(requests);

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest request : requests) {
            donations.add(buildRecurringDonation(request));
        }

        insert donations;

        List<Id> donationIds = new List<Id>();
        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }
        return donationIds;
    }

    /**
     * @description Validates every request up front so that an invalid request never
     *              results in partial DML.
     */
    private static void validate(List<GiftRequest> requests) {
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            Integer position = i + 1;

            if (request == null) {
                throw new RecurringGiftException('Request ' + position + ' is missing.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException('Request ' + position + ' is missing a contact.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException('Request ' + position + ' must have a positive amount.');
            }
            if (request.dayOfMonth == null
                || request.dayOfMonth < 1
                || request.dayOfMonth > DAY_OF_MONTH_LAST_DAY_INPUT) {
                throw new RecurringGiftException(
                    'Request ' + position + ' must have a day of month between 1 and 31.'
                );
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Request ' + position + ' is missing a start date.');
            }
        }
    }

    /**
     * @description Builds the monthly Enhanced Recurring Donation for one request.
     */
    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest request) {
        npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c();

        donation.npe03__Contact__c = request.contactId;
        donation.npe03__Amount__c = request.amount;
        donation.npe03__Date_Established__c = Date.today();

        donation.npsp__StartDate__c = request.startDate;
        donation.npsp__Status__c = STATUS_ACTIVE;
        donation.npsp__PaymentMethod__c = request.paymentMethod;
        donation.npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY;
        donation.npsp__InstallmentFrequency__c = INSTALLMENT_FREQUENCY_MONTHLY;

        // Fixed length when the form supplied a number of planned installments,
        // otherwise the recurring donation runs until it is closed.
        if (request.installments != null && request.installments > 0) {
            donation.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            donation.npe03__Installments__c = request.installments;
        } else {
            donation.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
        }

        // Day of Month: 1-30 are stored as given; 31 means "last day of the month",
        // which Enhanced Recurring Donations stores with its own Last Day option.
        if (request.dayOfMonth == DAY_OF_MONTH_LAST_DAY_INPUT) {
            donation.npsp__Day_of_Month__c = DAY_OF_MONTH_LAST_DAY;
            if (CAN_SET_ALWAYS_USE_LAST_DAY) {
                donation.npsp__Always_Use_Last_Day_Of_Month__c = true;
            }
        } else {
            donation.npsp__Day_of_Month__c = String.valueOf(request.dayOfMonth);
            if (CAN_SET_ALWAYS_USE_LAST_DAY) {
                donation.npsp__Always_Use_Last_Day_Of_Month__c = false;
            }
        }

        return donation;
    }
}
