/**
 * GiftService
 * Records a received gift (Closed Won donation) in NPSP with the Household Account model
 * and NPSP Payments enabled.
 *
 * A gift is created as an Opportunity on the contact's household account, with the contact
 * as primary contact (Donor role) and every other household member as Household Member.
 * Exactly one paid payment is created for the full amount.
 */
public with sharing class GiftService {

    private static final String OPP_RT_DEVELOPER_NAME = 'Donation';
    private static final String PRIMARY_ROLE_NAME    = 'Donor';
    private static final String HOUSEHOLD_ROLE_NAME  = 'Household Member';
    private static final String CLOSED_WON_STAGE     = 'Closed Won';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ---- Validate inputs -------------------------------------------------
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        // ---- Load the primary contact ---------------------------------------
        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact primaryContact = contacts[0];
        if (primaryContact.AccountId == null) {
            throw new IllegalArgumentException('Contact has no household account: ' + contactId);
        }

        // ---- Load the household members -------------------------------------
        List<Contact> householdMembers = [
            SELECT Id, FirstName, LastName
            FROM Contact
            WHERE AccountId = :primaryContact.AccountId
        ];

        // ---- Build opportunity name: <First> <Last> Donation <yyyy-MM-dd> ----
        String firstName = primaryContact.FirstName == null ? '' : primaryContact.FirstName;
        String lastName  = primaryContact.LastName  == null ? '' : primaryContact.LastName;
        String oppName   = (firstName + ' ' + lastName).trim() + ' Donation ' + String.valueOf(giftDate);

        // ---- Create the Opportunity -----------------------------------------
        Opportunity opp = new Opportunity(
            Name                       = oppName,
            AccountId                  = primaryContact.AccountId,
            Amount                     = amount,
            CloseDate                  = giftDate,
            StageName                  = CLOSED_WON_STAGE,
            npsp__Primary_Contact__c   = primaryContact.Id
        );

        Id donationRecordTypeId = getDonationRecordTypeId();
        if (donationRecordTypeId != null) {
            opp.RecordTypeId = donationRecordTypeId;
        }
        insert opp;

        // ---- Ensure exactly one paid payment for the full amount ------------
        ensureSinglePayment(opp.Id, amount, giftDate);

        // ---- Ensure contact roles are correct -------------------------------
        reconcileContactRoles(opp.Id, primaryContact.Id, householdMembers);

        return opp.Id;
    }

    /**
     * Returns the Id of the Opportunity "Donation" record type ONLY when it is available
     * to the running user. Otherwise returns null so the default record type is used
     * (avoids INVALID_CROSS_REFERENCE_KEY when the record type isn't assigned).
     */
    private static Id getDonationRecordTypeId() {
        Map<String, Schema.RecordTypeInfo> rtMap =
            Schema.SObjectType.Opportunity.getRecordTypeInfosByDeveloperName();
        if (rtMap != null && rtMap.containsKey(OPP_RT_DEVELOPER_NAME)) {
            Schema.RecordTypeInfo rt = rtMap.get(OPP_RT_DEVELOPER_NAME);
            if (rt != null && rt.isAvailable()) {
                return rt.getRecordTypeId();
            }
        }
        return null;
    }

    /**
     * Removes any auto-created payments and inserts a single paid payment
     * for the full amount on the given date.
     */
    private static void ensureSinglePayment(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
        ];
        if (!existingPayments.isEmpty()) {
            delete existingPayments;
        }

        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c    = oppId,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c   = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c           = true
        );
        insert payment;
    }

    /**
     * Ensures the opportunity has exactly one contact role per household member:
     *  - the primary contact  -> "Donor" (IsPrimary = true)
     *  - other household members -> "Household Member" (IsPrimary = false)
     * Any extra/duplicate roles and any roles for non-household contacts are removed.
     */
    private static void reconcileContactRoles(Id oppId, Id primaryContactId, List<Contact> householdMembers) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
        ];

        Map<Id, List<OpportunityContactRole>> rolesByContact = new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingRoles) {
            if (!rolesByContact.containsKey(ocr.ContactId)) {
                rolesByContact.put(ocr.ContactId, new List<OpportunityContactRole>());
            }
            rolesByContact.get(ocr.ContactId).add(ocr);
        }

        Set<Id> expectedContactIds = new Set<Id>{ primaryContactId };
        for (Contact m : householdMembers) {
            expectedContactIds.add(m.Id);
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();

        // Drop roles for contacts that are not part of the household.
        for (Id cId : rolesByContact.keySet()) {
            if (!expectedContactIds.contains(cId)) {
                toDelete.addAll(rolesByContact.get(cId));
            }
        }

        // Primary contact role.
        assignRole(oppId, primaryContactId, PRIMARY_ROLE_NAME, true,
                   rolesByContact, toInsert, toUpdate, toDelete);

        // Household member roles.
        for (Contact m : householdMembers) {
            if (m.Id == primaryContactId) {
                continue;
            }
            assignRole(oppId, m.Id, HOUSEHOLD_ROLE_NAME, false,
                       rolesByContact, toInsert, toUpdate, toDelete);
        }

        // Apply in order: delete extras first (to avoid duplicate IsPrimary issues),
        // then update the kept roles, then insert any missing ones.
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Collapses all existing roles for the contact into exactly one with the given
     * role name / IsPrimary value. Reuses an existing role if present, otherwise inserts.
     */
    private static void assignRole(
        Id oppId,
        Id contactId,
        String roleName,
        Boolean isPrimary,
        Map<Id, List<OpportunityContactRole>> rolesByContact,
        List<OpportunityContactRole> toInsert,
        List<OpportunityContactRole> toUpdate,
        List<OpportunityContactRole> toDelete
    ) {
        if (rolesByContact.containsKey(contactId)) {
            List<OpportunityContactRole> roles = rolesByContact.get(contactId);
            OpportunityContactRole keep = roles[0];
            keep.Role      = roleName;
            keep.IsPrimary = isPrimary;
            toUpdate.add(keep);
            for (Integer i = 1; i < roles.size(); i++) {
                toDelete.add(roles[i]);
            }
        } else {
            toInsert.add(new OpportunityContactRole(
                OpportunityId = oppId,
                ContactId     = contactId,
                Role          = roleName,
                IsPrimary     = isPrimary
            ));
        }
    }
}
