public with sharing class RecordAccessService {

    /**
     * UserRecordAccess is a special object: a single query returns at most 200 rows.
     * Asking for more raises "System.QueryException: Number of records exceeds limit: 200".
     * So we batch the record IDs; 2,000 IDs -> 10 queries, well within the 20 query budget.
     */
    @TestVisible
    private static final Integer ACCESS_QUERY_BATCH_SIZE = 200;

    /**
     * Returns the subset of recordIds that the running user is allowed to edit.
     *
     * The determination is delegated to UserRecordAccess.HasEditAccess, which already
     * accounts for object-level permissions (CRUD), ownership, sharing rules, manual
     * sharing, the role hierarchy, and View All / Modify All Data.
     *
     * @param recordIds  IDs to test. May be null, empty, contain nulls, and may span
     *                   multiple SObject types. Callers pass up to 2,000 IDs per call.
     * @return The editable subset of recordIds. Never null; empty when nothing qualifies.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableIds;
        }

        // Normalize input: drop nulls and duplicates.
        Set<Id> candidateIds = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                candidateIds.add(recordId);
            }
        }

        if (candidateIds.isEmpty()) {
            return editableIds;
        }

        Id runningUserId = UserInfo.getUserId();
        List<Id> idList = new List<Id>(candidateIds);
        Integer idCount = idList.size();

        // Query in batches of ACCESS_QUERY_BATCH_SIZE to stay under the 200-row limit.
        for (Integer start = 0; start < idCount; start += ACCESS_QUERY_BATCH_SIZE) {
            Integer end = Math.min(start + ACCESS_QUERY_BATCH_SIZE, idCount);

            List<Id> batch = new List<Id>();
            for (Integer i = start; i < end; i++) {
                batch.add(idList[i]);
            }

            // UserRecordAccess only returns a row for records the user can access.
            // A record that is absent from the result set is not editable by this user.
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                  AND RecordId IN :batch
            ]) {
                if (access.HasEditAccess) {
                    editableIds.add(access.RecordId);
                }
            }
        }

        return editableIds;
    }
}
